from collections import deque

def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); q.append(p)
            out.append((color,pts))
    return out

def has_hole(pts):
    r0=min(y for y,x in pts); r1=max(y for y,x in pts)
    c0=min(x for y,x in pts); c1=max(x for y,x in pts)
    cells={(y,x) for y,x in pts}; seen=set(); q=[]
    for y in range(r0,r1+1):
        for x in range(c0,c1+1):
            if y in (r0,r1) or x in (c0,c1):
                if (y,x) not in cells and (y,x) not in seen: seen.add((y,x)); q.append((y,x))
    while q:
        y,x=q.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if r0<=p[0]<=r1 and c0<=p[1]<=c1 and p not in cells and p not in seen:
                seen.add(p); q.append(p)
    return any((y,x) not in cells and (y,x) not in seen for y in range(r0,r1+1) for x in range(c0,c1+1))

def transform(grid):
    h,w=len(grid),len(grid[0]); objs=components(grid)
    holes=[]; solids=[]
    for color,pts in objs:
        obj={'color':color,'pts':pts,'hole':has_hole(pts)}
        (holes if obj['hole'] else solids).append(obj)
    placed=[]
    # Pack cavity-bearing objects upward, retaining their vertical order when their columns overlap.
    for group,up in ((holes,True),(solids,False)):
        order=sorted(group,key=lambda o:(min(y for y,x in o['pts']),min(x for y,x in o['pts'])),reverse=not up)
        for o in order:
            pts=o['pts']; delta=0; step=-1 if up else 1
            while True:
                nd=delta+step
                moved=[(y+nd,x) for y,x in pts]
                if min(y for y,x in moved)<0 or max(y for y,x in moved)>=h: break
                occupied={(y,x) for _,p in placed for y,x in p}
                if any(p in occupied for p in moved): break
                delta=nd
            moved=[(y+delta,x) for y,x in pts]
            placed.append((o['color'],moved))
    out=[[0]*w for _ in range(h)]
    for color,pts in placed:
        for y,x in pts: out[y][x]=color
    return out
