def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); q.append(p)
            out.append((color,pts))
    return out

def has_hole(pts):
    r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
    cells=set(pts); seen=set(); q=[]
    for y in range(r0,r1+1):
        for x in range(c0,c1+1):
            if (y in (r0,r1) or x in (c0,c1)) and (y,x) not in cells and (y,x) not in seen:
                seen.add((y,x)); q.append((y,x))
    while q:
        y,x=q.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if r0<=p[0]<=r1 and c0<=p[1]<=c1 and p not in cells and p not in seen: seen.add(p); q.append(p)
    return any((y,x) not in cells and (y,x) not in seen for y in range(r0,r1+1) for x in range(c0,c1+1))

def transform(grid):
    h,w=len(grid),len(grid[0]); holes=[]; solids=[]
    for color,pts in components(grid):
        (holes if has_hole(pts) else solids).append((color,pts))
    placed=[]
    # Hollow forms are sorted and packed from the top; other forms pack from the bottom.
    for group,up in ((holes,True),(solids,False)):
        group.sort(key=lambda o:(min(y for y,x in o[1]),min(x for y,x in o[1])), reverse=not up)
        for color,pts in group:
            occupied={(y,x) for _,p in placed for y,x in p}
            lo=-min(y for y,x in pts); hi=h-1-max(y for y,x in pts)
            deltas=range(lo,hi+1) if up else range(hi,lo-1,-1)
            for d in deltas:
                moved=[(y+d,x) for y,x in pts]
                if all(p not in occupied for p in moved):
                    placed.append((color,moved)); break
            else: placed.append((color,pts))
    out=[[0]*w for _ in range(h)]
    for color,pts in placed:
        for y,x in pts: out[y][x]=color
    return out
